package com.aditya.consumer; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Service; import java.util.concurrent.atomic.AtomicLong; @Service public class EventConsumer{private final AtomicLong count=new AtomicLong(); @KafkaListener(topics="orders.events",groupId="order-workers") public void consume(String e){count.incrementAndGet();System.out.println("EVENT="+e);} public long count(){return count.get();}}
